<?php require_once __DIR__.'/../includes/bootstrap.php';require_role(['admin','librarian']);verify_csrf();$id=(int)($_POST['id']??0);$s=$conn->prepare("UPDATE books SET is_archived=1 WHERE id=? AND NOT EXISTS(SELECT 1 FROM borrowings WHERE book_id=? AND status IN('pending','approved','borrowed')) AND NOT EXISTS(SELECT 1 FROM reservations WHERE book_id=? AND status IN('pending','approved','ready'))");$s->bind_param('iii',$id,$id,$id);$s->execute();if($s->affected_rows){log_activity($conn,(int)current_user()['id'],'book_archived','Book ID '.$id);flash('success','Book archived.');}else flash('error','Cannot archive a book with active borrowing or reservation transactions.');redirect('books.php');?>